package com.example

object MathPastPaper60QuestionsProvider {

    data class QuestionData(
        val topic: String,
        val text: String,
        val options: List<String>,
        val correctIdx: Int,
        val explanation: String
    )

    fun buildMathQuestion(year: Int, qNum: Int, yearStr: String, subjectTitle: String): PastPaperQuestion {
        val q = qNum.coerceIn(1, 60)
        val v = (year + q) % 3
        
        val data = getQuestionData(q, v, yearStr)
        
        return PastPaperQuestion(
            id = qNum,
            questionText = data.text,
            options = data.options,
            correctOptionIndex = data.correctIdx,
            explanationSinhala = data.explanation,
            topicCategory = data.topic,
            year = yearStr,
            subject = subjectTitle
        )
    }

    private fun getQuestionData(q: Int, v: Int, yearStr: String): QuestionData {
        val questions = listOf(
            // 1-10: Algebra Basics
            QuestionData("වීජ ගණිතය", "2x + 5 = 17 සමීකරණයේ x හි අගය සොයන්න.", listOf("x = 6", "x = 11", "x = 7", "x = 5"), 0, "2x = 17 - 5 => 2x = 12 => x = 6."),
            QuestionData("වීජ ගණිතය", "(x + 3)(x + 4) ප්‍රකාශනය ප්‍රසාරණය කළ විට ලැබෙන්නේ කුමක්ද?", listOf("x² + 7x + 12", "x² + 12x + 7", "x² + x + 12", "x² + 7"), 0, "x(x+4) + 3(x+4) = x² + 4x + 3x + 12 = x² + 7x + 12."),
            QuestionData("වීජ ගණිතය", "x² - 16 හි සාධක වෙන් කළ විට ලැබෙන ප්‍රකාශනය කුමක්ද?", listOf("(x - 4)(x + 4)", "(x - 4)²", "(x + 4)²", "x(x - 16)"), 0, "වර්ග දෙකක අන්තරය: a² - b² = (a - b)(a + b)."),
            QuestionData("වීජ ගණිතය", "3(x - 2) = 12 සමීකරණයේ x හි අගය කුමක්ද?", listOf("x = 6", "x = 4", "x = 5", "x = 2"), 0, "x - 2 = 4 => x = 6."),
            QuestionData("වීජ ගණිතය", "x/2 + 3 = 7 සමීකරණයේ x හි අගය සොයන්න.", listOf("x = 8", "x = 4", "x = 10", "x = 5"), 0, "x/2 = 4 => x = 8."),
            QuestionData("වීජ ගණිතය", "2x - 3y = 7 සහ x + 3y = 8 යන සමගාමී සමීකරණ විසඳූ විට x හි අගය කුමක්ද?", listOf("x = 5", "x = 3", "x = 1", "x = 15"), 0, "සමීකරණ දෙක එකතු කළ විට: 3x = 15 => x = 5."),
            QuestionData("වීජ ගණිතය", "x² + 5x + 6 ප්‍රකාශනයේ සාධක මොනවාද?", listOf("(x + 2)(x + 3)", "(x - 2)(x - 3)", "(x + 1)(x + 6)", "(x + 5)(x + 1)"), 0, "2 + 3 = 5 සහ 2 * 3 = 6 බැවින් සාධක (x+2) සහ (x+3) වේ."),
            QuestionData("වීජ ගණිතය", "3a²b * 4ab² හි අගය කුමක්ද?", listOf("12a³b³", "7a³b³", "12a²b²", "12ab"), 0, "3*4=12, a²*a=a³, b*b²=b³."),
            QuestionData("වීජ ගණිතය", "log₂ 8 හි අගය කුමක්ද?", listOf("3", "2", "4", "8"), 0, "2³ = 8 බැවින් log₂ 8 = 3 වේ."),
            QuestionData("වීජ ගණිතය", "3x > 12 අසමානතාවයේ විසඳුම කුමක්ද?", listOf("x > 4", "x < 4", "x = 4", "x > 3"), 0, "දෙපසම 3 න් බෙදූ විට x > 4 ලැබේ."),

            // 11-20: Arithmetic & Percentages
            QuestionData("අංක ගණිතය", "1/2 + 1/4 හි අගය කුමක්ද?", listOf("3/4", "2/6", "1/6", "1/2"), 0, "2/4 + 1/4 = 3/4."),
            QuestionData("අංක ගණිතය", "රු. 5000 කට ගත් භාණ්ඩයක් 10% ලාභයකට විකුණන විට විකුණුම් මිල කීයද?", listOf("රු. 5500", "රු. 5100", "රු. 4500", "රු. 6000"), 0, "5000 + (5000 * 0.10) = 5500."),
            QuestionData("අංක ගණිතය", "2 : 3 අනුපාතයට රු. 1000 ක් බෙදූ විට ලැබෙන කොටස් මොනවාද?", listOf("රු. 400 සහ රු. 600", "රු. 200 සහ රු. 300", "රු. 500 සහ රු. 500", "රු. 100 සහ රු. 900"), 0, "මුළු කොටස් 5 කි. 1000/5 = 200. එනම් 200*2 = 400 සහ 200*3 = 600."),
            QuestionData("අංක ගණිතය", "මිනිසුන් 4 දෙනෙකුට දින 6 කදී කළ හැකි වැඩක් මිනිසුන් 8 දෙනෙකුට කිරීමට දින කීයක් ගතවේද?", listOf("දින 3", "දින 12", "දින 2", "දින 4"), 0, "මුළු මිනිස් දින ගණන 4 * 6 = 24. 24 / 8 = 3."),
            QuestionData("අංක ගණිතය", "වාර්ෂික 12% සුළු පොලියට රු. 2000 ක් තැන්පත් කළ විට වසරක අවසානයේ ලැබෙන පොලිය කීයද?", listOf("රු. 240", "රු. 120", "රු. 2400", "රු. 200"), 0, "2000 * 12/100 = 240."),
            QuestionData("අංක ගණිතය", "භාණ්ඩයක වටිනාකම රු. 1200 කි. එයට 15% ක වැට් (VAT) බද්දක් එකතු කළ විට ගෙවිය යුතු මුළු මුදල කීයද?", listOf("රු. 1380", "රු. 1215", "රු. 1400", "රු. 1020"), 0, "1200 + (1200 * 0.15) = 1200 + 180 = 1380."),
            QuestionData("අංක ගණිතය", "වර්ගමූල 144 හි අගය කුමක්ද?", listOf("12", "14", "11", "24"), 0, "12 * 12 = 144 බැවින් අගය 12 වේ."),
            QuestionData("අංක ගණිතය", "0.25 භාගයක් ලෙස දැක්වූ විට නිවැරදි වන්නේ කුමක්ද?", listOf("1/4", "1/2", "1/5", "2/5"), 0, "25/100 = 1/4."),
            QuestionData("අංක ගණිතය", "පළමු ඉලක්කම් 5 හි සාමාන්‍යය කුමක්ද?", listOf("3", "2", "4", "5"), 0, "(1+2+3+4+5)/5 = 15/5 = 3."),
            QuestionData("අංක ගණිතය", "2⁵ හි අගය සොයන්න.", listOf("32", "10", "25", "16"), 0, "2 * 2 * 2 * 2 * 2 = 32."),

            // 21-30: Geometry
            QuestionData("ජ්‍යාමිතිය", "ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල එකතුව අංශක කීයක්ද?", listOf("180", "360", "90", "270"), 0, "ඕනෑම ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල එකතුව 180° කි."),
            QuestionData("ජ්‍යාමිතිය", "සෘජුකෝණී ත්‍රිකෝණයක පාද a, b සහ c (කර්ණය) නම් පයිතගරස් ප්‍රමේයය කුමක්ද?", listOf("a² + b² = c²", "a + b = c", "a² - b² = c²", "ab = c"), 0, "පයිතගරස් ප්‍රමේයය: a² + b² = c²."),
            QuestionData("ජ්‍යාමිතිය", "වෘත්තයක විෂ්කම්භය 14cm නම් එහි අරය කොපමණද?", listOf("7cm", "28cm", "14cm", "10cm"), 0, "අරය = විෂ්කම්භය / 2 = 14 / 2 = 7cm."),
            QuestionData("ජ්‍යාමිතිය", "සමාන්තරාස්‍රයක අභ්‍යන්තර කෝණවල එකතුව අංශක කීයක්ද?", listOf("360", "180", "540", "90"), 0, "ඕනෑම චතුරස්‍රයක අභ්‍යන්තර කෝණවල එකතුව 360° කි."),
            QuestionData("ජ්‍යාමිතිය", "සමාන්තර රේඛා දෙකක් තීර්යක් රේඛාවකින් කැපූ විට ඇතිවන ඒකාන්තර කෝණ කෙබඳුද?", listOf("සමාන වේ", "පරිපූරක වේ", "අසමාන වේ", "එකතුව 90 කි"), 0, "ඒකාන්තර කෝණ (Z හැඩය) සෑමවිටම සමාන වේ."),
            QuestionData("ජ්‍යාමිතිය", "වෘත්තයක පරිධිය සෙවීමේ සූත්‍රය කුමක්ද?", listOf("2πr", "πr²", "πd²", "2πr²"), 0, "වෘත්තයක පරිධිය = 2πr (මෙහි r අරයයි)."),
            QuestionData("ජ්‍යාමිතිය", "සමපාද ත්‍රිකෝණයක එක් අභ්‍යන්තර කෝණයක අගය කොපමණද?", listOf("60", "90", "45", "120"), 0, "180 / 3 = 60°."),
            QuestionData("ජ්‍යාමිතිය", "වෘත්තයක චාපයක දිග සෙවීමේදී භාවිත වන සූත්‍රය කුමක්ද?", listOf("(θ/360) * 2πr", "(θ/360) * πr²", "2πr", "πr²"), 0, "චාප දිග = (කේන්ද්‍රික කෝණය / 360) * 2πr."),
            QuestionData("ජ්‍යාමිතිය", "සෘජුකෝණාස්‍රයක දිග 8cm සහ පළල 5cm නම් එහි වර්ගඵලය කොපමණද?", listOf("40 cm²", "13 cm²", "26 cm²", "85 cm²"), 0, "වර්ගඵලය = දිග * පළල = 8 * 5 = 40 cm²."),
            QuestionData("ජ්‍යාමිතිය", "බහු අස්‍රයක බාහිර කෝණවල එකතුව සෑමවිටම කොපමණද?", listOf("360", "180", "නියත නැත", "540"), 0, "ඕනෑම බහු අස්‍රයක බාහිර කෝණවල එකතුව 360° කි."),

            // 31-40: Statistics & Probability
            QuestionData("සංඛ්‍යානය", "2, 4, 4, 5, 7, 8 යන දත්ත සමූහයේ මාදිලිය (Mode) කුමක්ද?", listOf("4", "5", "8", "7"), 0, "වැඩිම වාර ගණනක් යෙදී ඇති අගය (4) මාදිලියයි."),
            QuestionData("සංඛ්‍යානය", "3, 6, 9, 12, 15 යන දත්තවල මධ්‍යස්ථය (Median) කුමක්ද?", listOf("9", "12", "6", "15"), 0, "පිළිවෙළට සැකසූ විට මැද අගය 9 වේ."),
            QuestionData("සම්භාවිතාව", "සාධාරණ කාසියක් උඩ දැමූ විට 'සිරස' ලැබීමේ සම්භාවිතාව කොපමණද?", listOf("1/2", "1/4", "1", "0"), 0, "හැකි ප්‍රතිඵල 2 කි (සිරස, අගය). සිරස ලැබීම 1 කි. එබැවින් 1/2."),
            QuestionData("සම්භාවිතාව", "ඩයි කැටයක් ගැසූ විට 6 ට වඩා අඩු අගයක් ලැබීමේ සම්භාවිතාව කුමක්ද?", listOf("5/6", "1/6", "1", "1/2"), 0, "6 ට අඩු අගයන්: 1, 2, 3, 4, 5 (අගයන් 5 කි). මුළු අගයන් 6 කි. එබැවින් 5/6."),
            QuestionData("සංඛ්‍යානය", "දත්ත සමූහයක පරාසය (Range) යනු කුමක්ද?", listOf("උපරිම අගය - අවම අගය", "සියලු අගයන්හි එකතුව", "මැද අගය", "වැඩිපුරම ඇති අගය"), 0, "පරාසය යනු උපරිම සහ අවම අගයන් අතර වෙනසයි."),
            QuestionData("සංඛ්‍යානය", "වගුවක ඇති මුළු සංඛ්‍යාතය (Σf) 20 ක් සහ Σfx = 100 ක් නම් මධ්‍යන්‍යය (Mean) කීයද?", listOf("5", "20", "100", "2000"), 0, "මධ්‍යන්‍යය = Σfx / Σf = 100 / 20 = 5."),
            QuestionData("සංඛ්‍යානය", "සමුච්චිත සංඛ්‍යාත වක්‍රය (Ogive) ඇඳීමට භාවිත වන්නේ කුමක්ද?", listOf("සමුච්චිත සංඛ්‍යාතය", "සංඛ්‍යාතය", "පන්ති ප්‍රාන්තර", "මධ්‍ය අගය"), 0, "සමුච්චිත සංඛ්‍යාත වක්‍රය සඳහා සමුච්චිත සංඛ්‍යාතය අත්‍යවශ්‍ය වේ."),
            QuestionData("සම්භාවිතාව", "සිද්ධියක් සිදුවීමේ සම්භාවිතාව 0.7 නම් එය සිදු නොවීමේ සම්භාවිතාව කොපමණද?", listOf("0.3", "0.7", "1", "0"), 0, "1 - 0.7 = 0.3."),
            QuestionData("සංඛ්‍යානය", "පන්ති ප්‍රාන්තරයක (10 - 20) මධ්‍ය අගය කුමක්ද?", listOf("15", "10", "20", "30"), 0, "(10 + 20) / 2 = 15."),
            QuestionData("සංඛ්‍යානය", "පයි ප්‍රස්ථාරයක (Pie Chart) මුළු අගය නිරූපණය වන කෝණය කොපමණද?", listOf("360", "180", "90", "100"), 0, "වෘත්තයක කේන්ද්‍රික කෝණය 360° බැවින් මුළු අගය එයින් නිරූපණය වේ."),

            // 41-50: Mensuration
            QuestionData("මැනුම", "අරය r වූ වෘත්තයක වර්ගඵලය සෙවීමේ සූත්‍රය කුමක්ද?", listOf("πr²", "2πr", "4πr²", "1/2 πr²"), 0, "වෘත්තයක වර්ගඵලය = πr²."),
            QuestionData("මැනුම", "පැත්තක දිග 4cm වූ ඝනකයක (Cube) පරිමාව කොපමණද?", listOf("64 cm³", "16 cm³", "12 cm³", "48 cm³"), 0, "පරිමාව = 4 * 4 * 4 = 64 cm³."),
            QuestionData("මැනුම", "දිග l, පළල w සහ උස h වූ සෘජුකෝණාස්‍රාකාර ප්‍රිස්මයක පරිමාව කුමක්ද?", listOf("l * w * h", "l + w + h", "2(lw + wh + lh)", "1/2 lwh"), 0, "පරිමාව = දිග * පළල * උස."),
            QuestionData("මැනුම", "අරය 7cm වූ වෘත්තයක වර්ගඵලය සොයන්න (π = 22/7).", listOf("154 cm²", "44 cm²", "100 cm²", "144 cm²"), 0, "22/7 * 7 * 7 = 154."),
            QuestionData("මැනුම", "සිලින්ඩරයක පරිමාව සෙවීමේ සූත්‍රය කුමක්ද?", listOf("πr²h", "2πrh", "1/3 πr²h", "4/3 πr³"), 0, "සිලින්ඩරයක පරිමාව = පාදයේ වර්ගඵලය * උස = πr²h."),
            QuestionData("මැනුම", "පැත්තක දිග 5cm වූ සමචතුරස්‍රයක පරිමිතිය කොපමණද?", listOf("20cm", "25cm", "10cm", "15cm"), 0, "පරිමිතිය = 4 * 5 = 20cm."),
            QuestionData("මැනුම", "සමාන්තරාස්‍රයක වර්ගඵලය සෙවීමේ සූත්‍රය කුමක්ද?", listOf("ආධාරකයේ දිග * සිරස් උස", "දිග * පළල", "1/2 * ආධාරකය * උස", "පාදය²"), 0, "වර්ගඵලය = පාදය * උස."),
            QuestionData("මැනුම", "ත්‍රපීසියමක වර්ගඵලය සෙවීමේ සූත්‍රය කුමක්ද?", listOf("1/2(a + b)h", "1/2bh", "abh", "a + b + h"), 0, "වර්ගඵලය = 1/2 * (සමාන්තර පාදවල එකතුව) * සිරස් උස."),
            QuestionData("මැනුම", "අරය r වූ ගෝලයක (Sphere) පරිමාව කුමක්ද?", listOf("4/3 πr³", "4πr²", "πr²h", "1/3 πr²h"), 0, "ගෝලයක පරිමාව = 4/3 πr³."),
            QuestionData("මැනුම", "කෝණකයක (Cone) පරිමාව සෙවීමේ සූත්‍රය කුමක්ද?", listOf("1/3 πr²h", "πr²h", "4/3 πr³", "2πrh"), 0, "කෝණකයක පරිමාව = 1/3 * පාදයේ වර්ගඵලය * උස."),

            // 51-60: Trigonometry & Advanced
            QuestionData("ත්‍රිකෝණමිතිය", "සෘජුකෝණී ත්‍රිකෝණයක sin θ අර්ථ දැක්වෙන්නේ කෙසේද?", listOf("සම්මුඛ පාදය / කර්ණය", "බද්ධ පාදය / කර්ණය", "සම්මුඛ පාදය / බද්ධ පාදය", "කර්ණය / සම්මුඛ පාදය"), 0, "Sin = Opp / Hyp."),
            QuestionData("ත්‍රිකෝණමිතිය", "cos 60° හි අගය කුමක්ද?", listOf("1/2", "√3/2", "1", "0"), 0, "Cos 60 = 0.5."),
            QuestionData("ත්‍රිකෝණමිතිය", "tan 45° හි අගය කුමක්ද?", listOf("1", "0", "1/√3", "√3"), 0, "Tan 45 = 1."),
            QuestionData("කුලක", "A = {1, 2, 3} සහ B = {3, 4, 5} නම් A ∩ B කුමක්ද?", listOf("{3}", "{1, 2, 3, 4, 5}", "{1, 2}", "{}"), 0, "අන්තර්ඡේදනය යනු පොදු මූලද්‍රව්‍යයි. මෙහි 3 පොදු වේ."),
            QuestionData("කුලක", "කුලකයක ඇති මූලද්‍රව්‍ය ගණනය කිරීම සඳහා භාවිතා වන පදය කුමක්ද?", listOf("කාදිනල් අංකය", "අනුකුලකය", "පරිමිත කුලකය", "ශුන්‍ය කුලකය"), 0, "කුලකයක මූලද්‍රව්‍ය ගණන කාදිනල් අංකයයි."),
            QuestionData("ශ්‍රේණි", "2, 5, 8, 11, ... සමාන්තර ශ්‍රේණියේ පොදු අන්තරය කුමක්ද?", listOf("3", "2", "5", "4"), 0, "5 - 2 = 3. 8 - 5 = 3."),
            QuestionData("ශ්‍රේණි", "සමාන්තර ශ්‍රේණියක n වන පදය (Tn) සෙවීමේ සූත්‍රය කුමක්ද?", listOf("a + (n - 1)d", "a + nd", "n/2(2a + (n-1)d)", "ar^(n-1)"), 0, "Tn = a + (n-1)d."),
            QuestionData("වීජ ගණිතය", "x² - 5x + 6 = 0 වර්ගජ සමීකරණයේ මූලයන් මොනවාද?", listOf("2 සහ 3", "-2 සහ -3", "1 සහ 6", "5 සහ 6"), 0, "(x-2)(x-3) = 0 බැවින් x = 2 හෝ x = 3."),
            QuestionData("ත්‍රිකෝණමිතිය", "sin² θ + cos² θ හි අගය සෑමවිටම කීයද?", listOf("1", "0", "2", "-1"), 0, "ත්‍රිකෝණමිතික සර්වසාම්‍යයක් ලෙස sin² θ + cos² θ = 1 වේ."),
            QuestionData("ගණිතය", "සංඛ්‍යා දෙකක එකතුව 10 ක් සහ අන්තරය 2 ක් නම් එම සංඛ්‍යා මොනවාද?", listOf("6 සහ 4", "7 සහ 3", "8 සහ 2", "5 සහ 5"), 0, "6 + 4 = 10, 6 - 4 = 2.")
        )

        val idx = (q - 1).coerceIn(0, 59)
        val baseData = questions[idx]
        val finalTitle = "[$yearStr O/L - Q$q] " + baseData.text

        return QuestionData(baseData.topic, finalTitle, baseData.options, baseData.correctIdx, baseData.explanation)
    }
}
